<script setup lang="ts">
import { onMounted } from 'vue'; import { storeToRefs } from 'pinia'; import { RouterLink } from 'vue-router'; import FinanceScenarioBar from '../components/FinanceScenarioBar.vue'; import FinanceSubnav from '../components/FinanceSubnav.vue'; import { useFinanceStore } from '../runtime/finance-store'; import type { FinanceRole } from '../types'; import type { FinanceScenarioName } from '../../../../mock/handlers/finance-handler'; import './finance-views.css'; import './finance-receivable-views.css'
const store=useFinanceStore();const{receipts,loading,error,scenario,actor}=storeToRefs(store);const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;const date=(v:string)=>v.slice(0,16).replace('T',' ');const method={cash:'现金',bank:'银行转账',wechat:'微信',alipay:'支付宝',balance:'余额'} as const
async function refresh(){await store.loadReceipts()}async function changeScenario(v:FinanceScenarioName){await store.setScenario(v);await refresh()}async function changeRole(v:FinanceRole){await store.setRole(v);await refresh()}async function voidRow(id:string,version:number){const reason=window.prompt('请输入作废原因（1～200字）');if(reason)await store.voidReceipt(id,version,reason)}onMounted(refresh)
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>收款单</h1><p>保存即确认入账；未分配金额进入客户预收，已确认关键金额不可编辑。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="changeScenario" @role="changeRole"/></header><FinanceSubnav/><div class="finance-toolbar"><span>共 {{receipts.length}} 张收款单</span><div><button class="fin-button" @click="refresh">刷新</button><RouterLink v-if="actor.role!=='sales-supervisor'" class="fin-button primary" to="/finance/receipts/new">新增收款</RouterLink></div></div><div v-if="error" class="finance-state error"><strong>收款单加载失败</strong><p>{{error}}</p></div><div v-else-if="loading" class="finance-state"><strong>正在加载收款单…</strong></div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>收款单号/日期</th><th>客户</th><th class="fin-money">收款金额</th><th>方式/账户</th><th class="fin-money">已核销</th><th class="fin-money">可用预收</th><th>操作人</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in receipts" :key="row.id"><td><RouterLink :to="`/finance/receipts/${row.id}`"><strong>{{row.receiptNo}}</strong></RouterLink><small>{{date(row.occurredAt)}}</small></td><td>{{row.customerSnapshot.name}}<small>{{row.customerSnapshot.code}}</small></td><td class="fin-money">{{money(row.amountCents)}}</td><td>{{method[row.method]}}<small>{{row.accountId??'不产生资金流水'}}</small></td><td class="fin-money fin-income">{{money(row.allocatedCents)}}</td><td class="fin-money">{{money(row.availableCents)}}</td><td>{{row.operatorSnapshot.name}}</td><td><span class="fin-status" :class="row.status==='normal'?'enabled':'disabled'">{{row.status==='normal'?'正常':'已作废'}}</span></td><td><RouterLink :to="`/finance/receipts/${row.id}`">查看</RouterLink> <button v-if="row.status==='normal'&&row.allocatedCents===0&&actor.role!=='sales-supervisor'" class="fin-link-button danger" @click="voidRow(row.id,row.version)">作废</button></td></tr><tr v-if="!receipts.length"><td colspan="9">暂无收款单</td></tr></tbody></table></div></section></template>
